import { Schema } from "effect";

/**
 * Domain vocabulary shared by the server and the browser. Nothing here may
 * import server-only modules: the web client bundles this file.
 */

export const SessionId = Schema.String.check(Schema.isUUID()).pipe(
  Schema.brand("SessionId"),
);
export type SessionId = typeof SessionId.Type;

export const SentenceId = Schema.String.check(Schema.isUUID()).pipe(
  Schema.brand("SentenceId"),
);
export type SentenceId = typeof SentenceId.Type;

/** One time a sentence was shown in the browser; generated by the client. */
export const PresentationId = Schema.String.check(Schema.isUUID()).pipe(
  Schema.brand("PresentationId"),
);
export type PresentationId = typeof PresentationId.Type;

/**
 * How demanding newly generated practice sentences may be. Beginner asks
 * for single-clause sentences; intermediate allows any structure. A mode is
 * a generation constraint, not a measure of how hard a sentence turned out.
 */
export const PracticeMode = Schema.Literals(["beginner", "intermediate"]);
export type PracticeMode = typeof PracticeMode.Type;

/** What the learner is offered first when starting a new session. */
export const DEFAULT_PRACTICE_MODE: PracticeMode = "beginner";
/** Clients that do not choose a mode keep the original, unrestricted behaviour. */
export const UNSPECIFIED_PRACTICE_MODE: PracticeMode = "intermediate";

/**
 * Which practice the stream serves. Crosstalk practice writes sentences from
 * the recording's language (in a practice mode); curriculum practice teaches
 * grammar and function concepts using the recording's vocabulary.
 */
export const PracticeTrack = Schema.Literals(["crosstalk", "curriculum"]);
export type PracticeTrack = typeof PracticeTrack.Type;

/** What the page offers first when starting a new session. */
export const DEFAULT_PRACTICE_TRACK: PracticeTrack = "curriculum";
/** Clients that do not choose a track keep the original crosstalk practice. */
export const UNSPECIFIED_PRACTICE_TRACK: PracticeTrack = "crosstalk";

// ---------------------------------------------------------------------------
// Transcript: what the speech-to-text step heard, before any interpretation.
// ---------------------------------------------------------------------------

/** One uninterrupted stretch of speech by one speaker. */
export const TranscriptTurn = Schema.Struct({
  /** False when the transcriber doubts what it heard. */
  clear: Schema.optionalKey(Schema.Boolean),
  /** Language code such as "fi" or "en", when the transcriber reports it. */
  language: Schema.optionalKey(Schema.String),
  /** Speaker label ("native_speaker", "learner", "spk_1"); null if unknown. */
  speaker: Schema.NullOr(Schema.String),
  text: Schema.String,
});
export type TranscriptTurn = typeof TranscriptTurn.Type;

export const Transcript = Schema.Struct({
  /** Provider/model that produced the transcript, for debugging. */
  source: Schema.String,
  text: Schema.String,
  turns: Schema.Array(TranscriptTurn),
});
export type Transcript = typeof Transcript.Type;

// ---------------------------------------------------------------------------
// Session profile: the stable boundary every generated sentence stays within.
// ---------------------------------------------------------------------------

export const FinnishUtterance = Schema.Struct({
  english: Schema.String,
  finnish: Schema.String,
});
export type FinnishUtterance = typeof FinnishUtterance.Type;

export const VocabularyItem = Schema.Struct({
  english: Schema.String,
  /** The form(s) heard in the session. */
  heard: Schema.String,
  lemma: Schema.String,
});
export type VocabularyItem = typeof VocabularyItem.Type;

export const Construction = Schema.Struct({
  description: Schema.String,
  example: Schema.String,
});
export type Construction = typeof Construction.Type;

export const SessionProfile = Schema.Struct({
  constructions: Schema.Array(Construction),
  /** Finnish snippets dropped because the transcript looked unreliable. */
  discardedSnippets: Schema.Int,
  /** How the Finnish speaker talked: colloquial forms, pace, formality. */
  register: Schema.String,
  /** English summary of what the conversation was about. */
  summary: Schema.String,
  topics: Schema.Array(Schema.String),
  /** Finnish the learner reliably heard, with translations. */
  utterances: Schema.Array(FinnishUtterance),
  vocabulary: Schema.Array(VocabularyItem),
});
export type SessionProfile = typeof SessionProfile.Type;

// ---------------------------------------------------------------------------
// Session lifecycle as seen by the learner.
// ---------------------------------------------------------------------------

export const PreparationStage = Schema.Literals([
  /** Speech-to-text is running on the uploaded recording. */
  "transcribing",
  /** The transcript is being turned into a session profile. */
  "analyzing",
  /** The profile exists; the first practice sentences are being made. */
  "generating",
]);
export type PreparationStage = typeof PreparationStage.Type;

export const FailureReason = Schema.Literals([
  "transcription_failed",
  "analysis_failed",
  "insufficient_material",
]);
export type FailureReason = typeof FailureReason.Type;

export const SessionFailure = Schema.Struct({
  message: Schema.String,
  reason: FailureReason,
  /** Whether retrying the failed step could plausibly succeed. */
  retryable: Schema.Boolean,
});
export type SessionFailure = typeof SessionFailure.Type;

export const PracticeStats = Schema.Struct({
  answered: Schema.Int,
  /** Sentences with audio, waiting to be practiced. */
  buffered: Schema.Int,
  understood: Schema.Int,
});
export type PracticeStats = typeof PracticeStats.Type;

const SessionSummary = {
  createdAt: Schema.String,
  fileName: Schema.String,
  /** The mode new sentences are generated in. */
  mode: PracticeMode,
  sessionId: SessionId,
  /** The practice new sentences are served from. */
  track: PracticeTrack,
};

export const SessionView = Schema.Union([
  Schema.TaggedStruct("NoSession", {}),
  Schema.TaggedStruct("Preparing", {
    ...SessionSummary,
    stage: PreparationStage,
  }),
  Schema.TaggedStruct("Failed", {
    ...SessionSummary,
    failure: SessionFailure,
  }),
  Schema.TaggedStruct("Ready", {
    ...SessionSummary,
    stats: PracticeStats,
    summary: Schema.String,
    topics: Schema.Array(Schema.String),
  }),
]);
export type SessionView = typeof SessionView.Type;

// ---------------------------------------------------------------------------
// Practice.
// ---------------------------------------------------------------------------

/**
 * A sentence ready to be heard. The Finnish text, and for curriculum
 * sentences what they teach, are deliberately absent.
 */
export const PracticeItem = Schema.Struct({
  audioUrl: Schema.String,
  english: Schema.String,
  /** The mode a crosstalk sentence was generated in; null for curriculum. */
  mode: Schema.NullOr(PracticeMode),
  sentenceId: SentenceId,
  track: PracticeTrack,
});
export type PracticeItem = typeof PracticeItem.Type;

/**
 * How much of one curriculum's grammar the learner understands, as
 * estimated from curriculum evidence: established learning targets count
 * whole, others partly by how close they are to being established.
 */
export const CurriculumProgress = Schema.Struct({
  /** The catalog version the estimate is for. */
  curriculumId: Schema.String,
  established: Schema.Int,
  targets: Schema.Int,
  title: Schema.String,
  /** Share understood, from 0 to 1. */
  understood: Schema.Finite,
  /** The same share from responses before `since`, when it was asked for. */
  understoodBefore: Schema.NullOr(Schema.Finite),
});
export type CurriculumProgress = typeof CurriculumProgress.Type;

export const PracticeModeChange = Schema.Struct({ mode: PracticeMode });
export type PracticeModeChange = typeof PracticeModeChange.Type;

export const PracticeTrackChange = Schema.Struct({ track: PracticeTrack });
export type PracticeTrackChange = typeof PracticeTrackChange.Type;

export const PracticeResponse = Schema.Struct({
  /** The presentation the learner responded in; links the interaction log. */
  presentationId: PresentationId,
  replayCount: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
  translationRevealed: Schema.Boolean,
  understood: Schema.Boolean,
});
export type PracticeResponse = typeof PracticeResponse.Type;

// ---------------------------------------------------------------------------
// Presentation log: an append-only record of what happened while a sentence
// was on screen, kept for studying comprehension. It never steers practice.
// ---------------------------------------------------------------------------

/** Bump when the meaning of an event or its fields changes. */
export const PRESENTATION_EVENT_SCHEMA_VERSION = 1;
export const MAX_PRESENTATION_EVENTS_PER_BATCH = 100;

const Uuid = Schema.String.check(Schema.isUUID());
const Millis = Schema.Finite.check(Schema.isGreaterThanOrEqualTo(0));

/**
 * What happened. Playback events share a `playbackId` from the request that
 * started them, so an attempt can be followed from request to its outcome.
 */
export const PresentationEventDetail = Schema.TaggedUnion({
  /**
   * Playback was asked for. `priorStarts` counts earlier playbacks that
   * started in this presentation, so a tap with `priorStarts > 0` is a replay.
   */
  PlayRequested: {
    playbackId: Uuid,
    priorStarts: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
    trigger: Schema.Literals(["auto", "tap"]),
  },
  /** Playback ran to the end of the audio. */
  PlaybackEnded: { playbackId: Uuid, positionMs: Millis },
  /** The browser could not start or continue playback. */
  PlaybackFailed: {
    playbackId: Uuid,
    reason: Schema.String.check(Schema.isMaxLength(200)),
  },
  /** The app stopped playback before the end. */
  PlaybackInterrupted: {
    playbackId: Uuid,
    positionMs: Millis,
    reason: Schema.Literals(["replay", "answered", "left"]),
  },
  /** Playback stopped before the end for a reason outside the app. */
  PlaybackPaused: { playbackId: Uuid, positionMs: Millis },
  /** Audio is actually playing; duration is null until the browser knows it. */
  PlaybackStarted: {
    audioDurationMs: Schema.NullOr(Millis),
    playbackId: Uuid,
  },
  /** The sentence became the current one on screen. */
  Presented: { autoplay: Schema.Boolean, visible: Schema.Boolean },
  /** The learner marked the sentence; mirrors the stored response. */
  Responded: { understood: Schema.Boolean },
  TranslationRevealed: {},
  /** The page was hidden or shown again, e.g. by switching apps. */
  VisibilityChanged: { visible: Schema.Boolean },
});
export type PresentationEventDetail = typeof PresentationEventDetail.Type;

export const PresentationEvent = Schema.Struct({
  /** Monotonic milliseconds since the presentation began. */
  clientElapsedMs: Millis,
  /** Client wall-clock time, for lining up with server timestamps. */
  clientEpochMs: Millis,
  detail: PresentationEventDetail,
  /** Retries resend the same id; the server stores each id once. */
  eventId: Uuid,
  /** Order within the presentation, starting at 0. */
  sequence: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
});
export type PresentationEvent = typeof PresentationEvent.Type;

export const PresentationEventBatch = Schema.Struct({
  events: Schema.Array(PresentationEvent).check(
    Schema.isMinLength(1),
    Schema.isMaxLength(MAX_PRESENTATION_EVENTS_PER_BATCH),
  ),
  schemaVersion: Schema.Literal(PRESENTATION_EVENT_SCHEMA_VERSION),
});
export type PresentationEventBatch = typeof PresentationEventBatch.Type;

// ---------------------------------------------------------------------------
// Errors that cross the HTTP boundary.
// ---------------------------------------------------------------------------

export class SessionAlreadyExists extends Schema.TaggedError<SessionAlreadyExists>()(
  "SessionAlreadyExists",
  {},
  { httpApiStatus: 409 },
) {}

export class NoActiveSession extends Schema.TaggedError<NoActiveSession>()(
  "NoActiveSession",
  {},
  { httpApiStatus: 409 },
) {}

export class RecordingRejected extends Schema.TaggedError<RecordingRejected>()(
  "RecordingRejected",
  { message: Schema.String },
  { httpApiStatus: 422 },
) {}

export class NotRetryable extends Schema.TaggedError<NotRetryable>()(
  "NotRetryable",
  {},
  { httpApiStatus: 409 },
) {}

export class SentenceNotFound extends Schema.TaggedError<SentenceNotFound>()(
  "SentenceNotFound",
  { sentenceId: Schema.String },
  { httpApiStatus: 404 },
) {}

export class AlreadyAnswered extends Schema.TaggedError<AlreadyAnswered>()(
  "AlreadyAnswered",
  { sentenceId: Schema.String },
  { httpApiStatus: 409 },
) {}

/**
 * A presentation id already belongs to another sentence, or an event reused
 * a sequence number with a different id. Retrying cannot fix either.
 */
export class PresentationConflict extends Schema.TaggedError<PresentationConflict>()(
  "PresentationConflict",
  { message: Schema.String, presentationId: Schema.String },
  { httpApiStatus: 409 },
) {}
